package dev.veltraph.client.navigation;
import dev.veltraph.client.rewarp.FarmMaintenanceLease;
import dev.veltraph.client.world.Vec3;
import org.junit.jupiter.api.Test;
import static org.junit.jupiter.api.Assertions.*;
/** Pure issuer/control counterexamples; authentic native Binding capture remains separately required. */
class LegacyMaintenancePublicationIdentityTest {
 final Object root=new Object(),farm=new Object(),helper=new Object(),p=new Object(),w=new Object(),c=new Object(),config=new Object(),service=new Object(),candidate=new Object();
 final FarmMaintenanceLease issuer=new FarmMaintenanceLease();
 final FarmMaintenanceLease.Token token=issuer.prepare(farm,helper,1,1000);
 final Vec3 goal=new Vec3(1,70,1);
 LegacyMaintenancePublicationIdentityTest(){assertTrue(issuer.commit(token));}
 MaintenanceMovementAuthorityFrame frame(){return MaintenanceMovementAuthorityFrame.capture(new MaintenanceMovementAuthorityFrame.Observation(
  new MaintenanceMovementAuthorityFrame.Pair(issuer,new Object(),new Object(),farm,helper,token,new Object(),null),
  new MaintenanceMovementAuthorityFrame.Context(p,w,c,config,1,2),issuer.state(),SharedMovementPolicy.Purpose.GENERAL_TRAVEL,goal,goal,
  helper,token,"helper","helper",true,true,true,true,true,true,true,true,true)).orElseThrow();}
 LegacyTravelPublicationIdentity.State state(Object camera,long g,long e,long serial,Object active,boolean usable){return new LegacyTravelPublicationIdentity.State(root,helper,helper,camera,p,w,c,config,3,1,service,g,e,serial,active,true,true,usable);}
 LegacyTravelPublicationIdentity.Lease admitted(){var s=state(token,4,9,20,null,true);return LegacyTravelPublicationIdentity.Lease.admitMaintenance(s,s,candidate,frame(),7,7);}
 @Test void normalCaptureAndAdmissionCannotBorrowOpaqueCamera(){var s=state(token,4,9,20,candidate,true);assertNull(LegacyTravelPublicationIdentity.Lease.capture(s));s=state(token,4,9,20,null,true);assertNull(LegacyTravelPublicationIdentity.Lease.admit(s,s,candidate,7,7));}
 @Test void typedIssuedPairAdmitsSeparateHelperAndCameraToken(){var x=admitted();assertNotNull(x);assertTrue(x.current(state(token,4,9,20,candidate,true)));assertFalse(x.current(state(helper,4,9,20,candidate,true)));}
 @Test void arbitraryForeignOpaqueOwnerCannotMatchProviderFrame(){var s=state(new Object(),4,9,20,null,true);assertNull(LegacyTravelPublicationIdentity.Lease.admitMaintenance(s,s,candidate,frame(),7,7));}
 @Test void replacementIssuedTokenRevokesOldCameraRole(){var x=admitted();issuer.cancel(token,"replace");issuer.clear();var next=issuer.prepare(farm,helper,2,1000);assertTrue(issuer.commit(next));assertNotSame(token,next);assertFalse(x.current(state(next,4,9,20,candidate,true)));assertFalse(x.cleanupCurrent(state(next,4,9,20,candidate,false)));}
 @Test void actualOwnCameraPublicationUsesIssuedCameraRole(){var x=admitted();var before=state(token,4,9,20,candidate,true);var after=state(token,4,10,21,candidate,true);assertTrue(x.published(new LegacyTravelPublicationIdentity.Publication(before,after,21)));assertEquals(21,x.ticket());assertTrue(x.current(after));assertFalse(x.current(state(helper,4,10,21,candidate,true)));}
 @Test void sameParentRawNewPlanSameEpochRevokesCleanup(){var x=admitted();var before=state(token,4,9,20,candidate,true);var after=state(token,4,9,21,candidate,true);assertTrue(x.published(new LegacyTravelPublicationIdentity.Publication(before,after,21)));assertFalse(x.cleanupCurrent(state(token,4,9,22,candidate,true)));}
 @Test void queuedRequestAndQualifiedActualSourcePublicationKeepOneLeg(){var x=admitted();var before=state(token,4,9,20,candidate,true);var queue=state(token,5,9,20,candidate,true);assertTrue(x.queued(before,queue));assertEquals(0,x.ticket());var published=state(token,5,10,21,candidate,true);assertTrue(x.refreshedSource(queue,published,5,10,21));assertTrue(x.current(published));assertEquals(21,x.ticket());}
 @Test void foreignQueuedPublicationCannotCopyPermission(){var x=admitted();var before=state(token,4,9,20,candidate,true);var queue=state(token,5,9,20,candidate,true);assertTrue(x.queued(before,queue));assertFalse(x.refreshedSource(queue,state(token,6,10,21,candidate,true),6,10,21));assertFalse(x.refreshedSource(queue,state(helper,5,10,21,candidate,true),5,10,21));assertEquals(0,x.ticket());}
 @Test void actualSourceCancelIsExactGenerationEpochAndStableSerial(){var x=admitted();var before=state(token,4,9,20,candidate,true);var queue=state(token,5,9,20,candidate,true);assertTrue(x.queued(before,queue));var published=state(token,5,10,21,candidate,true);assertTrue(x.refreshedSource(queue,published,5,10,21));var cancelled=state(token,6,11,21,candidate,true);assertTrue(x.cancelled(published,cancelled,true));assertEquals(0,x.ticket());assertTrue(x.cleanupCurrent(cancelled));}
 @Test void noEffectAdmissionAbaRefusesMaintenanceHandoff(){var old=state(token,4,9,20,null,true);assertNull(LegacyTravelPublicationIdentity.Lease.admitMaintenanceAfter(old,old,candidate,frame(),old,old,7,7,9));assertNotNull(LegacyTravelPublicationIdentity.Lease.admitMaintenanceAfter(old,old,candidate,frame(),old,old,7,7,7));}
 @Test void closedExactMaintenanceLegRetainsStrictContinuationWithoutPublishing(){var x=admitted();x.closed();var old=state(token,4,9,20,null,true);assertTrue(x.ownsRetiredContinuation(old,true,8,8));assertFalse(x.current(state(token,4,9,20,candidate,true)));assertFalse(x.ownsRetiredContinuation(old,true,8,10));}
 @Test void changedProviderPwcAndConfigCannotAdmit(){var frame=frame();var s=new LegacyTravelPublicationIdentity.State(root,helper,helper,token,p,new Object(),c,config,3,1,service,4,9,20,null,true,true,true);assertNull(LegacyTravelPublicationIdentity.Lease.admitMaintenance(s,s,candidate,frame,7,7));s=new LegacyTravelPublicationIdentity.State(root,helper,helper,token,p,w,c,new Object(),3,1,service,4,9,20,null,true,true,true);assertNull(LegacyTravelPublicationIdentity.Lease.admitMaintenance(s,s,candidate,frame,7,7));}
 @Test void actualOwnEndThenPolicyAbaRefreshesCleanupOnly(){var x=admitted();var before=state(token,4,9,20,candidate,true);var queued=state(token,5,9,20,candidate,true);assertTrue(x.queued(before,queued));var oldPublication=state(token,5,10,21,candidate,true);long[] revision={3};Runnable aba=()->{revision[0]++;revision[0]++;};aba.run();var revoked=new LegacyTravelPublicationIdentity.State(root,helper,helper,token,p,w,c,config,revision[0],1,service,5,10,21,candidate,true,true,false);assertFalse(x.refreshedSource(queued,revoked,5,10,21));assertTrue(x.refreshedSourceCleanup(revoked,5,10,21));assertTrue(x.cleanupCurrent(revoked));assertFalse(x.current(revoked));assertEquals(21,x.ticket());assertTrue(x.cancelled(revoked,new LegacyTravelPublicationIdentity.State(root,helper,helper,token,p,w,c,config,revision[0],1,service,6,11,21,candidate,true,true,false),true));}
 @Test void cleanupEndRefreshCannotAdoptForeignGenerationOrSkippedSerial(){var x=admitted();assertTrue(x.queued(state(token,4,9,20,candidate,true),state(token,5,9,20,candidate,true)));assertFalse(x.refreshedSourceCleanup(state(token,6,10,21,candidate,false),6,10,21));assertFalse(x.refreshedSourceCleanup(state(token,5,10,22,candidate,false),5,10,22));assertEquals(0,x.ticket());assertEquals(9,x.epoch());}
 @Test void cleanupRefreshForeignCameraAfterActualOwnEndIsRefused(){var x=admitted();assertTrue(x.queued(state(token,4,9,20,candidate,true),state(token,5,9,20,candidate,true)));Object[] camera={token};Runnable callback=()->camera[0]=new Object();callback.run();assertFalse(x.refreshedSourceCleanup(state(camera[0],5,10,21,candidate,false),5,10,21));assertEquals(20,x.serial());}
 @Test void cleanupRefreshCannotReplaceOriginalPolicyPermission(){var x=admitted();assertTrue(x.queued(state(token,4,9,20,candidate,true),state(token,5,9,20,candidate,true)));var changed=new LegacyTravelPublicationIdentity.State(root,helper,helper,token,p,w,c,config,8,1,service,5,10,21,candidate,true,true,false);assertTrue(x.refreshedSourceCleanup(changed,5,10,21));assertFalse(x.current(changed));x.closed();var closed=new LegacyTravelPublicationIdentity.State(root,helper,helper,token,p,w,c,config,8,1,service,5,10,21,null,true,true,false);assertFalse(x.ownsRetiredContinuation(closed,true,8,8));}
 @Test void cleanupRefreshCannotBorrowReplacedStoreOrActiveLeg(){var x=admitted();assertTrue(x.queued(state(token,4,9,20,candidate,true),state(token,5,9,20,candidate,true)));var foreign=new LegacyTravelPublicationIdentity.State(root,helper,helper,token,p,w,c,new Object(),9,1,service,5,10,21,candidate,true,true,false);assertFalse(x.refreshedSourceCleanup(foreign,5,10,21));assertFalse(x.refreshedSourceCleanup(state(token,5,10,21,new Object(),false),5,10,21));}
 @Test void nativeClosedNullAuthorityIsNotAnOwnPublicationRefresh(){var x=admitted();assertTrue(x.queued(state(token,4,9,20,candidate,true),state(token,5,9,20,candidate,true)));var closed=new LegacyTravelPublicationIdentity.State(root,helper,null,null,p,w,c,config,9,1,service,5,10,21,candidate,true,false,false);assertFalse(x.refreshedSourceCleanup(closed,5,10,21));assertEquals(0,x.ticket());}
}
